\draw[thick] (2.0,1.4) .. controls (3.0,0.2) and (3.0,-0.2) .. (2.0,-1.4);
\foreach \y in {-1.2,-0.8,-0.4,0,0.4,0.8,1.2} {\draw[thin] (3.05,\y)--++(0.25,0);}
\node[font=\small] at (2.6,1.75) {Mirror Y};
